package store
import("context";"path/filepath";"testing")
func TestMFADevices(t *testing.T){ctx:=context.Background();s,_:=Open(filepath.Join(t.TempDir(),"t.db"));defer s.Close();if e:=s.Migrate(ctx);e!=nil{t.Fatal(e)};if e:=s.CreateUser(ctx,"u","x","user","");e!=nil{t.Fatal(e)};u,_:=s.UserByName(ctx,"u");ids:=[]int64{};for _,n:=range []string{"iPhone","Company Phone","Backup Phone"}{id,e:=s.AddMFADevice(ctx,u.ID,n,"SECRET"+n);if e!=nil{t.Fatal(e)};ids=append(ids,id);if e=s.VerifyMFADevice(ctx,u.ID,id);e!=nil{t.Fatal(e)}};if _,e:=s.AddMFADevice(ctx,u.ID,"fourth","SECRET4");e==nil{t.Fatal("4th MFA device must be rejected")};secrets,e:=s.VerifyMFASecrets(ctx,u.ID);if e!=nil||len(secrets)!=3{t.Fatalf("want 3 secrets got %d err=%v",len(secrets),e)};if e=s.DeleteMFADevice(ctx,u.ID,ids[1]);e!=nil{t.Fatal(e)};ds,_:=s.MFADevices(ctx,u.ID);if len(ds)!=2{t.Fatalf("want 2 devices got %d",len(ds))}}
